import pandas as pd, numpy as np, statsmodels.api as sm, warnings
warnings.filterwarnings('ignore')
df=pd.read_csv('data.csv'); n=len(df); NB=20
edges=np.quantile(df.D,np.linspace(0,1,NB+1)); edges[0]=-np.inf; edges[-1]=np.inf
didx=np.digitize(df.D.values,edges[1:-1])
def qbin(v,k):
    e=np.quantile(df[v].values,np.linspace(0,1,k+1)); e[0]=-np.inf; e[-1]=np.inf
    return np.digitize(df[v].values,e[1:-1])
def controls():
    P=[];nm=[]
    for v,kk in [('log_hist_days',8),('log_pre_gmv',8),('orders',6),('cat_share',6),('tenure',6)]:
        b=qbin(v,kk)
        for j in range(1,kk): P.append((b==j).astype(float)); nm.append(f'{v}_{j}')
    reg=df.region.values.astype(int); tie=df.tier.values.astype(int)
    for r in range(1,5): P.append((reg==r).astype(float)); nm.append(f'R{r}')
    for t in range(1,4): P.append((tie==t).astype(float)); nm.append(f'T{t}')
    bh=qbin('log_hist_days',6)
    for r in range(5):
        for j in range(1,6): P.append(((reg==r)&(bh==j)).astype(float)); nm.append(f'R{r}xH{j}')
    return P,nm
def fit_design(tmode='bins',post=False):
    P=[np.ones(n)];nm=['const']
    if tmode=='bins':
        for k in range(1,NB): P.append((didx==k).astype(float)); nm.append(f'Db{k}')
    else:
        P.append(df.D.values); nm.append('D')
    Pc,nmc=controls(); P+=Pc; nm+=nmc
    if post: P.append(df.post_orders.values); nm.append('post_orders')
    X=np.column_stack(P)
    Q,R=np.linalg.qr(X); dg=np.abs(np.diag(R)); keep=[i for i in range(X.shape[1]) if dg[i]>1e-9*dg.max()]
    return X[:,keep], [nm[i] for i in keep]
Xb,nmb=fit_design('bins'); Xl,nml=fit_design('lin'); Xp,nmp_=fit_design('lin',post=True)
Dm=np.array([df.D.values[didx==k].mean() for k in range(NB)])
def run(X,y):
    m=sm.OLS(y,X).fit(cov_type='HC1'); return m, np.asarray(m.cov_params())
outcomes={'原始 dY':df.dY.values,'趋势调整 dY-placebo':(df.dY-df.dY_placebo).values}
