import pandas as pd, numpy as np, statsmodels.api as sm, warnings
warnings.filterwarnings('ignore')
df=pd.read_csv('data.csv'); n=len(df)
def qbin(v,k,data=None):
    d=df if data is None else data
    e=np.quantile(df[v].values,np.linspace(0,1,k+1)); e[0]=-np.inf; e[-1]=np.inf
    return np.digitize(d[v].values,e[1:-1])
reg=df.region.values.astype(int); tie=df.tier.values.astype(int)
def ctrl(fine=8, inter=6, extra_inter2=False):
    P=[]
    for v,kk in [('log_hist_days',fine),('log_pre_gmv',fine),('orders',fine-2),('cat_share',6),('tenure',6)]:
        b=qbin(v,kk)
        for j in range(1,kk): P.append((b==j).astype(float))
    for r in range(1,5): P.append((reg==r).astype(float))
    for t in range(1,4): P.append((tie==t).astype(float))
    bh=qbin('log_hist_days',inter)
    for r in range(5):
        for j in range(1,inter): P.append(((reg==r)&(bh==j)).astype(float))
    if extra_inter2:
        bp=qbin('log_pre_gmv',5); bd=qbin('D',5)
        for a in range(1,5):
            for c in range(1,5): P.append(((bp==a)&(bd==c)).astype(float))
    return np.column_stack(P)
def fitbeta(extra_cols, y, X0):
    X=np.column_stack([np.ones(n),extra_cols,X0])
    Q,R=np.linalg.qr(X); dg=np.abs(np.diag(R)); keep=[i for i in range(X.shape[1]) if dg[i]>1e-9*dg.max()]
    Xk=X[:,keep]; m=sm.OLS(y,Xk).fit(cov_type='HC1'); V=np.asarray(m.cov_params())
    return m,V,keep,Xk.shape[1]
print('=== 控制集精细度对 beta_D（线性D）的影响 ===')
for fine,inter,ex,lab in [(8,6,False,'粗(fine8,inter6)'),(12,10,False,'中(fine12,inter10)'),(16,12,False,'细(fine16,inter12)'),(16,12,True,'细+preGMV×D分箱交互')]:
    C=ctrl(fine,inter,ex)
    for yv,ylab in [(df.dY.values,'dY'),((df.dY-df.dY_placebo).values,'dY-placebo')]:
        m,V,k,p=fitbeta(df.D.values.reshape(-1,1),yv,C)
