    print(f'  beta_D={m.params[1]: .4f} (se {np.sqrt(V[1,1]):.4f})   beta_post_orders={m.params[2]: .4f} (se {np.sqrt(V[2,2]):.4f})  p={m.pvalues[2]:.3f}')
